<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Falling Sand Sandbox</title>
    <style>
        :root {
            --bg-color: #1e1e2e;
            --text-color: #cdd6f4;
            --accent-color: #89b4fa;
            --button-hover: #313244;
            --sand-color: #eab38a;
            --water-color: #3b82f6;
            --wall-color: #94a3b8;
            --acid-color: #4ade80;
        }

        body {
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            background-color: var(--bg-color);
            color: var(--text-color);
            margin: 0;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            min-height: 100vh;
        }

        h1 {
            margin-bottom: 20px;
            font-weight: 300;
        }

        .controls {
            margin-bottom: 20px;
            display: flex;
            gap: 10px;
            flex-wrap: wrap;
            justify-content: center;
        }

        button.material-btn {
            background-color: #45475a;
            color: var(--text-color);
            border: none;
            padding: 12px 16px;
            border-radius: 8px;
            font-size: 16px;
            cursor: pointer;
            transition: all 0.2s ease;
            box-shadow: 0 4px 6px rgba(0, 0, 0, 0.3);
        }

        button.material-btn:hover {
            background-color: var(--button-hover);
            transform: translateY(-1px);
        }

        button.material-btn.active {
            background-color: #585b70;
            box-shadow: inset 0 -2px 4px rgba(0,0,0,0.3);
        }

        #sand {
            border-radius: 8px;
            cursor: crosshair;
            box-shadow: 0 10px 20px rgba(0,0,0,0.5);
            margin-bottom: 20px;
        }

        button#clear {
            background-color: #ef4444;
            color: white;
        }

        button#clear:hover {
            background-color: #dc2626;
        }
    </style>
</head>
<body>
    <h1>Falling Sand Sandbox</h1>

    <div class="controls">
        <button id="mat-sand" class="material-btn active">Sand</button>
        <button id="mat-water" class="material-btn">Water</button>
        <button id="mat-wall" class="material-btn">Wall</button>
        <button id="mat-acid" class="material-btn">Acid</button>
        <button id="mat-empty" class="material-btn">Eraser</button>
    </div>

    <canvas id="sand" width="400" height="400"></canvas>

    <div class="controls">
        <button id="clear" class="material-btn">Clear Canvas</button>
    </div>

    <script>
        // Define the grid dimensions
        const GRID_W = 100;
        const GRID_H = 100;

        // Material constants
        const EMPTY = "empty";
        const SAND = "sand";
        const WATER = "water";
        const WALL = "wall";
        const ACID = "acid";

        // Grid array - store materials as strings for clarity
        let grid = [];

        // Current material to paint
        let currentMaterial = SAND;

        // Canvas setup
        const canvas = document.getElementById('sand');
        const ctx = canvas.getContext('2d');

        // Adjust canvas size to match the simulation grid scaled up
        const SCALE = 4;  // Each cell is 4x4 pixels on screen
        canvas.width = GRID_W * SCALE;
        canvas.height = GRID_H * SCALE;

        // Initialize empty grid
        function initGrid() {
            grid = new Array(GRID_H).fill(null).map(() => new Array(GRID_W).fill(EMPTY));
        }

        // Material colors for rendering
        const materialColors = {
            [EMPTY]: "#1e1e2e",
            [SAND]: "#eab38a",
            [WATER]: "#3b82f6",
            [WALL]: "#94a3b8",
            [ACID]: "#4ade80"
        };

        // Initialize the grid
        initGrid();

        // Paint function for drawing on the canvas
        function paint(x, y) {
            // Convert mouse coordinates to grid coordinates
            const rect = canvas.getBoundingClientRect();
            const gridX = Math.floor((x - rect.left) * GRID_W / canvas.width);
            const gridY = Math.floor((y - rect.top) * GRID_H / canvas.height);

            if (gridX >= 0 && gridX < GRID_W && gridY >= 0 && gridY < GRID_H) {
                // Add a bit of noise for more natural-looking deposits
                for (let dy = -1; dy <= 1; dy++) {
                    for (let dx = -1; dx <= 1; dx++) {
                        if (Math.random() > 0.5) continue;

                        const px = gridX + dx;
                        const py = gridY + dy;

                        if (px >= 0 && px < GRID_W && py >= 0 && py < GRID_H) {
                            set(px, py, currentMaterial);
                        }
                    }
                }
            }
        }

        // Set a cell in the grid
        function set(x, y, material) {
            if (x >= 0 && x < GRID_W && y >= 0 && y < GRID_H) {
                grid[y][x] = material;
            }
        }

        // Get a cell from the grid
        function get(x, y) {
            if (x >= 0 && x < GRID_W && y >= 0 && y < GRID_H) {
                return grid[y][x];
            }
            return null; // Out of bounds
        }

        // Clear the entire grid
        function clearGrid() {
            initGrid();
        }

        // Update simulation for one time step
        function tick() {
            // Process from bottom to top to prevent particles from teleporting
            for (let y = GRID_H - 2; y >= 0; y--) {
                // Shuffle the x-direction for each row to avoid left/right bias
                const directions = Math.random() < 0.5 ? [1, -1] : [-1, 1];

                for (let x = 0; x < GRID_W; x++) {
                    const material = grid[y][x];

                    // Skip empty cells and walls (walls don't move)
                    if (material === EMPTY || material === WALL) continue;

                    // Check cell below
                    const belowY = y + 1;

                    // Sand specific rules
                    if (material === SAND) {
                        if (get(x, belowY) === EMPTY || get(x, belowY) === WATER || get(x, belowY) === ACID) {
                            // Fall straight down or swap with liquid
                            const target = get(x, belowY);
                            grid[y][x] = target;
                            grid[belowY][x] = SAND;
                        } else if (get(x - 1, belowY) === EMPTY || get(x - 1, belowY) === WATER || get(x - 1, belowY) === ACID) {
                            // Slide left
                            const target = get(x - 1, belowY);
                            grid[y][x] = target;
                            grid[belowY][x - 1] = SAND;
                        } else if (get(x + 1, belowY) === EMPTY || get(x + 1, belowY) === WATER || get(x + 1, belowY) === ACID) {
                            // Slide right
                            const target = get(x + 1, belowY);
                            grid[y][x] = target;
                            grid[belowY][x + 1] = SAND;
                        }
                    }

                    // Water specific rules
                    else if (material === WATER) {
                        if (get(x, belowY) === EMPTY) {
                            grid[y][x] = EMPTY;
                            grid[belowY][x] = WATER;
                        } else if (get(x - 1, y) === EMPTY && Math.random() > 0.5) {
                            // Spread left
                            grid[y][x] = EMPTY;
                            grid[y][x - 1] = WATER;
                        } else if (get(x + 1, y) === EMPTY && Math.random() > 0.5) {
                            // Spread right
                            grid[y][x] = EMPTY;
                            grid[y][x + 1] = WATER;
                        }
                    }

                    // Acid specific rules
                    else if (material === ACID) {
                        const belowMaterial = get(x, belowY);

                        // Check if acid should dissolve something below or beside it
                        let dissolved = false;
                        if (belowMaterial === SAND || belowMaterial === WALL) {
                            grid[y][x] = EMPTY;  // Acid disappears
                            grid[belowY][x] = EMPTY;  // Target also disappears
                            dissolved = true;
                        } else if ((get(x - 1, y) === SAND || get(x - 1, y) === WALL) && Math.random() > 0.5) {
                            grid[y][x] = EMPTY;  // Acid disappears
                            grid[y][x - 1] = EMPTY;  // Target also disappears
                            dissolved = true;
                        } else if ((get(x + 1, y) === SAND || get(x + 1, y) === WALL) && Math.random() > 0.5) {
                            grid[y][x] = EMPTY;  // Acid disappears
                            grid[y][x + 1] = EMPTY;  // Target also disappears
                            dissolved = true;
                        }

                        if (!dissolved) {
                            // If not dissolving, move like water
                            if (get(x, belowY) === EMPTY) {
                                grid[y][x] = EMPTY;
                                grid[belowY][x] = ACID;
                            } else if (get(x - 1, y) === EMPTY && Math.random() > 0.5) {
                                // Spread left
                                grid[y][x] = EMPTY;
                                grid[y][x - 1] = ACID;
                            } else if (get(x + 1, y) === EMPTY && Math.random() > 0.5) {
                                // Spread right
                                grid[y][x] = EMPTY;
                                grid[y][x + 1] = ACID;
                            }
                        }
                    }
                }
            }
        }

        // Render the grid to canvas
        function render() {
            for (let y = 0; y < GRID_H; y++) {
                for (let x = 0; x < GRID_W; x++) {
                    ctx.fillStyle = materialColors[grid[y][x]];
                    ctx.fillRect(x * SCALE, y * SCALE, SCALE, SCALE);
                }
            }
        }

        // Animation loop
        function animate() {
            tick();
            render();
            requestAnimationFrame(animate);
        }

        // Setup UI controls
        document.getElementById('mat-sand').addEventListener('click', () => {
            currentMaterial = SAND;
            updateButtonActiveState('mat-sand');
        });

        document.getElementById('mat-water').addEventListener('click', () => {
            currentMaterial = WATER;
            updateButtonActiveState('mat-water');
        });

        document.getElementById('mat-wall').addEventListener('click', () => {
            currentMaterial = WALL;
            updateButtonActiveState('mat-wall');
        });

        document.getElementById('mat-acid').addEventListener('click', () => {
            currentMaterial = ACID;
            updateButtonActiveState('mat-acid');
        });

        document.getElementById('mat-empty').addEventListener('click', () => {
            currentMaterial = EMPTY;
            updateButtonActiveState('mat-empty');
        });

        document.getElementById('clear').addEventListener('click', clearGrid);

        function updateButtonActiveState(activeId) {
            const buttons = document.querySelectorAll('.material-btn');
            buttons.forEach(btn => btn.classList.remove('active'));

            const activeBtn = document.getElementById(activeId);
            if (activeBtn) {
                activeBtn.classList.add('active');
            }
        }

        // Canvas mouse events for painting
        let isDrawing = false;
        canvas.addEventListener('mousedown', (e) => {
            isDrawing = true;
            paint(e.clientX, e.clientY);
        });

        canvas.addEventListener('mousemove', (e) => {
            if (isDrawing) {
                paint(e.clientX, e.clientY);
            }
        });

        window.addEventListener('mouseup', () => {
            isDrawing = false;
        });

        // Expose the simulation API to window
        window.sim = {
            w: GRID_W,
            h: GRID_H,

            tick(n) {
                for (let i = 0; i < n; i++) {
                    tick();
                }
            },

            get(x, y) {
                return get(x, y);
            },

            set(x, y, material) {
                set(x, y, material);
                render(); // Update display immediately when setting manually
            },

            clear() {
                clearGrid();
                render();
            }
        };

        // Start the animation
        animate();

        // Initial render to show empty grid
        render();
    </script>
</body>
</html>
